def transform(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    # Rays of each marker color follow the diagonal direction demonstrated by its position around the 2x2 block.
    # For each nonzero singleton not part of the 2x2 object, extend diagonally outward from the block.
    cells={c:[] for c in range(3,10)}
    for r in range(h):
      for c in range(w):
       if g[r][c] not in (0,2): cells[g[r][c]].append((r,c))
    # Direction mapping established by four corner markers: 3=up-right, 6=down-right, 8=up-left, 7=down-left.
    dirs={3:(-1,1),6:(1,1),8:(-1,-1),7:(1,-1)}
    for color, pts in cells.items():
      dr,dc=dirs.get(color,(0,0))
      for r,c in pts:
       rr,cc=r+dr,c+dc
       while 0<=rr<h and 0<=cc<w:
        if g[rr][cc]==0: g[rr][cc]=color
        rr+=dr; cc+=dc
    return g
