def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Every diagonal marker launches a ray in the direction of its corner orientation;
    # the ray has the marker's original color.
    for r in range(h):
        for c in range(w):
            z=grid[r][c]
            if z not in (3,6,7,8):
                continue
            # determine diagonal away from nearest 2x2 block
            blocks=[]
            for y in range(h-1):
                for x in range(w-1):
                    if all(grid[yy][xx]==2 for yy in (y,y+1) for xx in (x,x+1)):
                        blocks.append((y,x))
            if blocks:
                y,x=min(blocks,key=lambda p:abs(p[0]+.5-r)+abs(p[1]+.5-c))
                dr=-1 if r<=y else 1
                dc=-1 if c<=x else 1
            else:
                dr=-1 if r<h/2 else 1; dc=-1 if c<w/2 else 1
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if g[rr][cc]==0:
                    g[rr][cc]=z
                rr+=dr;cc+=dc
    return g
