def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    roles = [(-1, -1, -1, -1, 8), (-1, 2, -1, 1, 3),
             (2, -1, 1, -1, 7), (2, 2, 1, 1, 6)]
    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                continue
            for ro, co, dr, dc, color in roles:
                sr, sc = r + ro, c + co
                if not (0 <= sr < h and 0 <= sc < w) or grid[sr][sc] == 0:
                    continue
                rr, cc = sr, sc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] == 0 or (rr, cc) == (sr, sc):
                        out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
